// n8n hands the Error Trigger a single item describing the failed execution.
const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};

const stack = String(err.stack || '').split('\n').slice(0, 6).join('\n');
const node  = err.node?.name || ex.lastNodeExecuted || 'unknown node';
const msg   = String(err.message || 'Unknown error').slice(0, 900);

// Classify so on-call knows whether to act now or at leisure.
let severity = 'error', hint = 'Open the execution and re-run from the failed node.';
if (/429|rate limit/i.test(msg)) {
  severity = 'warning';
  hint = 'HubSpot rate limit hit. Lower `pageSize` or raise `apiThrottleMs` in ⚙️ Global Config.';
} else if (/401|403|unauthor|forbidden|invalid.*token|expired/i.test(msg)) {
  severity = 'critical';
  hint = 'HubSpot/Slack credential problem. Check the private-app token and its scopes.';
} else if (/timeout|ETIMEDOUT|ECONNRESET|socket hang up|ENOTFOUND/i.test(msg)) {
  severity = 'warning';
  hint = 'Transient network issue. The node already retried 3x — safe to re-run.';
} else if (/merge/i.test(node)) {
  severity = 'critical';
  hint = 'A MERGE step failed. Verify in HubSpot whether the merge partially applied before re-running.';
}

const icon = { critical: ':rotating_light:', error: ':x:', warning: ':warning:' }[severity];

const text = [
  `${icon} *CRM Hygiene & Dedup — execution failed* (${severity.toUpperCase()})`,
  `*Workflow:* ${wf.name || 'n/a'}`,
  `*Failed node:* \`${node}\``,
  `*Mode:* ${ex.mode || 'n/a'}  ·  *When:* ${ex.lastNodeExecuted ? (ex.executionTime || '') : ''} ${new Date().toISOString().slice(0,19).replace('T',' ')} UTC`,
  '',
  '```' + msg + '```',
  `:bulb: ${hint}`,
  ex.url ? `<${ex.url}|Open the failed execution →>` : '',
].filter(Boolean).join('\n');

return [{ json: {
  severity, node, message: msg, hint, stack,
  workflowName: wf.name || null, workflowId: wf.id || null,
  executionId: ex.id || null, executionUrl: ex.url || null,
  text,
} }];
